START TRANSACTION;

DROP TABLE IF EXISTS temp_import_data_2026;

CREATE TABLE temp_import_data_2026 (
    id_temp INT AUTO_INCREMENT PRIMARY KEY,
    cliente VARCHAR(100), dni VARCHAR(15), ruc VARCHAR(11),
    razon_social VARCHAR(200), rubro VARCHAR(100),
    direccion_fiscal VARCHAR(255), distrito_empresa VARCHAR(100),
    provincia_empresa VARCHAR(100), departamento_empresa VARCHAR(100),
    nombre_comercial VARCHAR(200), direccion_sede VARCHAR(255),
    distrito_sede VARCHAR(100), provincia_sede VARCHAR(100),
    departamento_sede VARCHAR(100), referencia TEXT,
    coordenadas_gps VARCHAR(50), contacto_nombre VARCHAR(100),
    contacto_telefono VARCHAR(20), contacto_telefono_2 VARCHAR(20),
    contacto_email VARCHAR(100), fecha_inicio DATE, fecha_fin DATE,
    frecuencia VARCHAR(50), peso_limite_kg DECIMAL(10,2),
    tarifa DECIMAL(10,2), tipo_tarifa VARCHAR(50) DEFAULT 'por_servicio',
    observaciones TEXT, horario VARCHAR(100), metodo_pago VARCHAR(50),
    status VARCHAR(50), renovacion_contrato VARCHAR(50),
    id_cliente INT, id_empresa INT, id_sede INT, id_contrato INT,
    procesado BOOLEAN DEFAULT FALSE, error_msg TEXT
);

