-- ============================================
-- PROCEDIMIENTO PARA MIGRAR A TABLAS FINALES
-- ============================================
DELIMITER //

CREATE PROCEDURE sp_migrate_data_2026()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_cliente VARCHAR(100); DECLARE v_dni VARCHAR(15); DECLARE v_ruc VARCHAR(11);
    DECLARE v_razon_social VARCHAR(200); DECLARE v_direccion VARCHAR(255);
    DECLARE v_distrito VARCHAR(100); DECLARE v_provincia VARCHAR(100);
    DECLARE v_departamento VARCHAR(100); DECLARE v_nombre_comercial VARCHAR(200);
    DECLARE v_contacto VARCHAR(100); DECLARE v_telefono1 VARCHAR(20);
    DECLARE v_telefono2 VARCHAR(20); DECLARE v_email VARCHAR(100);
    DECLARE v_referencia TEXT; DECLARE v_coordenadas VARCHAR(50);
    DECLARE v_fecha_inicio DATE; DECLARE v_fecha_fin DATE;
    DECLARE v_peso DECIMAL(10,2); DECLARE v_tarifa DECIMAL(10,2);
    DECLARE v_observaciones TEXT; DECLARE v_id_temp INT;
    DECLARE v_id_cliente INT; DECLARE v_id_empresa INT;
    DECLARE v_id_sede INT; DECLARE v_id_contrato INT;
    
    DECLARE cur CURSOR FOR 
        SELECT id_temp, cliente, dni, ruc, razon_social, direccion_fiscal,
               distrito_empresa, provincia_empresa, departamento_empresa,
               nombre_comercial, contacto_nombre, contacto_telefono, contacto_telefono_2,
               contacto_email, referencia, coordenadas_gps, fecha_inicio, fecha_fin,
               peso_limite_kg, tarifa, observaciones
        FROM temp_import_data_2026 WHERE procesado = FALSE;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1
            @sqlstate = RETURNED_SQLSTATE, @errno = MYSQL_ERRNO, @text = MESSAGE_TEXT;
        UPDATE temp_import_data_2026 
        SET error_msg = CONCAT('Error ', @errno, ': ', @text),
            procesado = TRUE 
        WHERE id_temp = v_id_temp;
    END;
    
    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_id_temp, v_cliente, v_dni, v_ruc, v_razon_social, v_direccion,
                       v_distrito, v_provincia, v_departamento, v_nombre_comercial,
                       v_contacto, v_telefono1, v_telefono2, v_email, v_referencia,
                       v_coordenadas, v_fecha_inicio, v_fecha_fin, v_peso, v_tarifa, v_observaciones;
        IF done THEN LEAVE read_loop; END IF;
        
        SET v_id_cliente = NULL; SET v_id_empresa = NULL;
        
        IF v_dni IS NOT NULL AND v_dni != '' THEN
            SELECT id_cliente INTO v_id_cliente FROM Cliente WHERE dni = v_dni LIMIT 1;
        END IF;
        
        IF v_id_cliente IS NULL THEN
            INSERT INTO Cliente (nombre, dni, tipo_documento, activo)
            VALUES (COALESCE(NULLIF(v_cliente, ''), v_razon_social, 'SIN NOMBRE'), v_dni, 'DNI', 1);
            SET v_id_cliente = LAST_INSERT_ID();
        END IF;
        
        IF v_ruc IS NOT NULL AND v_ruc != '' THEN
            SELECT id_empresa INTO v_id_empresa FROM Empresa WHERE ruc = v_ruc LIMIT 1;
        END IF;
        
        IF v_id_empresa IS NULL THEN
            INSERT INTO Empresa (id_cliente, razon_social, ruc, direccion_fiscal, 
                                distrito, provincia, departamento, activo)
            VALUES (v_id_cliente, COALESCE(NULLIF(v_razon_social, ''), 'SIN RAZON SOCIAL'), 
                   v_ruc, v_direccion, v_distrito, v_provincia, v_departamento, 1);
            SET v_id_empresa = LAST_INSERT_ID();
        END IF;
        
        INSERT INTO Sede (id_empresa, nombre_comercial, direccion, distrito, provincia,
                         departamento, referencia, coordenadas_gps, contacto_nombre,
                         contacto_telefono, contacto_telefono_2, contacto_email, activo)
        VALUES (v_id_empresa, COALESCE(NULLIF(v_nombre_comercial, ''), v_razon_social, 'SIN NOMBRE'), 
               v_direccion, v_distrito, v_provincia, v_departamento, v_referencia, 
               v_coordenadas, v_contacto, v_telefono1, v_telefono2, v_email, 1);
        SET v_id_sede = LAST_INSERT_ID();
        
        INSERT INTO ContratoServicio (id_sede, fecha_inicio, fecha_fin, frecuencia,
                                     peso_limite_kg, tarifa, tipo_tarifa, observaciones, activo)
        VALUES (v_id_sede, v_fecha_inicio, v_fecha_fin, 'mensual',
               v_peso, v_tarifa, 'por_servicio', v_observaciones, 1);
        SET v_id_contrato = LAST_INSERT_ID();
        
        UPDATE temp_import_data_2026 
        SET id_cliente = v_id_cliente, id_empresa = v_id_empresa,
            id_sede = v_id_sede, id_contrato = v_id_contrato, procesado = TRUE
        WHERE id_temp = v_id_temp;
    END LOOP;
    CLOSE cur;
    
    SELECT 'Migración completada' AS mensaje;
    SELECT COUNT(*) AS total FROM temp_import_data_2026;
    SELECT COUNT(*) AS exitosos FROM temp_import_data_2026 WHERE procesado = TRUE AND error_msg IS NULL;
    SELECT COUNT(*) AS errores FROM temp_import_data_2026 WHERE error_msg IS NOT NULL;
END //

DELIMITER ;

-- Para ejecutar: CALL sp_migrate_data_2026();
-- Para verificar: SELECT * FROM temp_import_data_2026 WHERE procesado = FALSE OR error_msg IS NOT NULL;

COMMIT;
